/**
 * @title CurveYield System Component
 * @notice CurveYield is a decentralized NGO building optimized DeFi systems for the good of all.
 *
 * @dev CurveYield integrates specialized AMM infrastructure, tokenized yield strategies, credit
 * markets, and protocol-owned liquidity into a unified, capital-efficient liquidity stack governed
 * by an open, international DAO community.
 *
 * Protocol operations are enhanced by cross-chain bridging and messaging, MEV capture systems,
 * off-chain to on-chain automation, and peer-to-peer data networks.
 *
 * This contract is one component of the CurveYield system.
 *
 * CurveYield uses proven DeFi primitives where possible and adds targeted coordination and
 * capital-efficiency-enhancing contracts where needed. Users and integrators must review
 * CurveYield documentation before use.
 *
 * Learn more:
 * dApp: https://curveyield.com & https://curveyield.org
 *
 * Decentralized links may have limited or delayed availability during periods of high network activity:
 * https://curveyield.eth.limo
 * https://curveyield.dao
 *
 * Note: curveyield.dao may require a Brave Browser or an Unstoppable Domains browser plugin to use.
 */

pragma solidity 0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable, Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {ICurveYieldvlSDTStaking} from "./interfaces/ICurveYield.sol";
import {ICurveYieldVaultStrategy} from "./interfaces/ICurveYieldVaultStrategy.sol";
import {ICurveYieldVault} from "./interfaces/ICurveYieldVault.sol";
import {ICurveYieldOmniRouter} from "./interfaces/ICurveYieldOmniRouter.sol";
import {ICurveYieldvlSDTLocker} from "./interfaces/ICurveYield.sol";

/// @notice Beefy V7-style strategy for the CurveYield revenue vault.
contract CurveYieldRevenueStrategyV7 is
    ICurveYieldVaultStrategy,
    Ownable2Step,
    Pausable,
    ReentrancyGuard
{
    using SafeERC20 for IERC20;

    uint256 internal constant BPS = 10_000;
    uint256 public constant MAX_WITHDRAW_FEE_BPS = 100;
    uint256 public constant MAX_PERFORMANCE_FEE_BPS = 900;
    uint256 public constant MAX_CALL_FEE_BPS = 100;
    uint256 public constant MAX_TOTAL_HARVEST_FEE_BPS = 1_000;

    address public immutable override vault;
    IERC20 public immutable WANT;
    IERC20 public immutable SDT;
    ICurveYieldvlSDTStaking public immutable REVENUE_STAKING;

    address public constant USDC = 0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48;
    ICurveYieldOmniRouter public immutable OMNI_ROUTER;
    ICurveYieldvlSDTLocker public immutable LOCKER;

    struct PendingStrategyWithdrawal {
        uint256 grossAmount;
        uint256 reservedIdle;
        uint256 stakingRequestId;
        uint64 unlockTime;
    }

    uint256 public nextStrategyWithdrawalId = 1;
    uint256 public reservedWithdrawalAssets;
    mapping(uint256 => PendingStrategyWithdrawal) public pendingStrategyWithdrawals;

    uint16 public immutable withdrawalFeeBps;
    uint16 public immutable performanceFeeBps;
    uint16 public immutable callFeeBps;

    error ZeroAddress();
    error ZeroAmount();
    error NotVault();
    error NotSelf();
    error InvalidFee();
    error InvalidWithdrawalRequest();
    error WithdrawalNotReady(uint256 unlockTime);

    event Deposit(uint256 amount);
    event Withdraw(uint256 requested, uint256 sent, uint256 retainedFee);
    event StrategyWithdrawalRequested(
        uint256 indexed requestId, uint256 grossAmount, uint256 reservedIdle, uint256 stakingRequestId, uint256 unlockTime
    );
    event StrategyWithdrawalCompleted(uint256 indexed requestId, uint256 sent);
    event StrategyWithdrawalExitedInstantly(uint256 indexed requestId, uint256 sent, uint256 retainedFee);
    event Harvest(address indexed caller, uint256 grossWant, uint256 callerFee, uint256 performanceFee);

    constructor(
        address initialOwner_,
        address vault_,
        address want_,
        address sdt_,
        address revenueStaking_,
        address locker_,
        address omniRouter_,
        uint16 withdrawalFeeBps_,
        uint16 performanceFeeBps_,
        uint16 callFeeBps_
    ) Ownable(initialOwner_) {
        if (
            initialOwner_ == address(0) || vault_ == address(0) || want_ == address(0)
                || sdt_ == address(0)
                || revenueStaking_ == address(0) || locker_ == address(0) || omniRouter_ == address(0)
        ) revert ZeroAddress();
        if (withdrawalFeeBps_ > MAX_WITHDRAW_FEE_BPS) revert InvalidFee();
        if (
            performanceFeeBps_ > MAX_PERFORMANCE_FEE_BPS
                || callFeeBps_ > MAX_CALL_FEE_BPS
                || uint256(performanceFeeBps_) + uint256(callFeeBps_) > MAX_TOTAL_HARVEST_FEE_BPS
        ) revert InvalidFee();
        vault = vault_;
        WANT = IERC20(want_);
        SDT = IERC20(sdt_);
        REVENUE_STAKING = ICurveYieldvlSDTStaking(revenueStaking_);
        LOCKER = ICurveYieldvlSDTLocker(locker_);
        OMNI_ROUTER = ICurveYieldOmniRouter(omniRouter_);
        withdrawalFeeBps = withdrawalFeeBps_;
        performanceFeeBps = performanceFeeBps_;
        callFeeBps = callFeeBps_;
    }

    modifier onlyVault() {
        if (msg.sender != vault) revert NotVault();
        _;
    }

    modifier onlySelf() {
        if (msg.sender != address(this)) revert NotSelf();
        _;
    }

    function want() external view override returns (address) {
        return address(WANT);
    }

    function beforeDeposit() external override onlyVault {
        if (paused()) return;
        try this.harvestBeforeDeposit() {} catch {}
    }

    function harvestBeforeDeposit() external onlySelf nonReentrant {
        _harvest(address(0));
    }

    function beforeDepositStrict() external override onlyVault nonReentrant {
        if (paused()) revert EnforcedPause();
        _harvest(address(0));
    }

    /// @notice Best-effort harvest used immediately before vault withdrawal pricing.
    /// @dev Harvest/conversion failures are intentionally swallowed so principal withdrawals remain live.
    function beforeWithdraw() external override onlyVault {
        if (paused()) return;
        try this.harvestBeforeWithdraw() {} catch {}
    }

    function harvestBeforeWithdraw() external onlySelf nonReentrant {
        _harvest(address(0));
    }

    function beforeWithdrawStrict() external override onlyVault nonReentrant {
        if (paused()) revert EnforcedPause();
        _harvest(address(0));
    }

    function deposit() external override onlyVault whenNotPaused {
        _depositIdle();
    }

    function withdrawInstant(uint256 amount) external override onlyVault nonReentrant returns (uint256 received) {
        if (amount == 0) return 0;

        uint256 idle = _unreservedIdle();
        uint256 fromIdle = idle < amount ? idle : amount;
        received = fromIdle;

        uint256 remaining = amount - fromIdle;
        if (remaining != 0) {
            uint256 active = REVENUE_STAKING.activeBalance(address(this));
            uint256 requested = remaining < active ? remaining : active;
            if (requested != 0) received += REVENUE_STAKING.withdrawImmediate(requested, address(this));
        }

        uint256 fee = Math.mulDiv(received, withdrawalFeeBps, BPS);
        received -= fee;
        if (received != 0) WANT.safeTransfer(vault, received);
        if (fee != 0) WANT.safeTransfer(ICurveYieldVault(vault).feeReceiver(), fee);
        emit Withdraw(amount, received, fee);
    }

    function requestWithdrawal(uint256 amount)
        external
        override
        onlyVault
        nonReentrant
        returns (uint256 requestId, uint256 unlockTime)
    {
        if (amount == 0) revert ZeroAmount();

        uint256 idle = _unreservedIdle();
        uint256 reservedIdle = idle < amount ? idle : amount;
        uint256 remaining = amount - reservedIdle;
        uint256 stakingRequestId;

        if (remaining != 0) {
            stakingRequestId = REVENUE_STAKING.requestWithdrawal(remaining);
            (address requestOwner, uint128 requestAmount, uint64 requestUnlockTime, bool completed) =
                REVENUE_STAKING.withdrawalRequests(stakingRequestId);
            if (requestOwner != address(this) || uint256(requestAmount) != remaining || completed) {
                revert InvalidWithdrawalRequest();
            }
            unlockTime = requestUnlockTime;
        } else {
            unlockTime = block.timestamp + REVENUE_STAKING.WITHDRAWAL_DELAY();
        }

        reservedWithdrawalAssets += reservedIdle;
        requestId = nextStrategyWithdrawalId++;
        pendingStrategyWithdrawals[requestId] = PendingStrategyWithdrawal({
            grossAmount: amount,
            reservedIdle: reservedIdle,
            stakingRequestId: stakingRequestId,
            unlockTime: uint64(unlockTime)
        });
        emit StrategyWithdrawalRequested(requestId, amount, reservedIdle, stakingRequestId, unlockTime);
    }

    function completeWithdrawal(uint256 requestId)
        external
        override
        onlyVault
        nonReentrant
        returns (uint256 received)
    {
        PendingStrategyWithdrawal memory request = pendingStrategyWithdrawals[requestId];
        if (request.grossAmount == 0) revert InvalidWithdrawalRequest();
        if (block.timestamp < request.unlockTime) revert WithdrawalNotReady(request.unlockTime);

        delete pendingStrategyWithdrawals[requestId];
        reservedWithdrawalAssets -= request.reservedIdle;
        received = request.reservedIdle;
        if (request.stakingRequestId != 0) {
            received += REVENUE_STAKING.completeQueuedWithdrawal(request.stakingRequestId, address(this));
        }
        if (received != 0) WANT.safeTransfer(vault, received);
        emit StrategyWithdrawalCompleted(requestId, received);
    }

    function withdrawPendingInstant(uint256 requestId)
        external
        override
        onlyVault
        nonReentrant
        returns (uint256 received)
    {
        PendingStrategyWithdrawal memory request = pendingStrategyWithdrawals[requestId];
        if (request.grossAmount == 0) revert InvalidWithdrawalRequest();

        delete pendingStrategyWithdrawals[requestId];
        reservedWithdrawalAssets -= request.reservedIdle;
        received = request.reservedIdle;
        if (request.stakingRequestId != 0) {
            received += REVENUE_STAKING.withdrawQueuedImmediate(request.stakingRequestId, address(this));
        }

        uint256 fee = Math.mulDiv(received, withdrawalFeeBps, BPS);
        received -= fee;
        if (received != 0) WANT.safeTransfer(vault, received);
        if (fee != 0) WANT.safeTransfer(ICurveYieldVault(vault).feeReceiver(), fee);
        emit StrategyWithdrawalExitedInstantly(requestId, received, fee);
    }

    function harvest() external nonReentrant whenNotPaused returns (uint256 grossWant) {
        grossWant = _harvest(msg.sender);
    }

    function harvest(address callFeeRecipient) external nonReentrant whenNotPaused returns (uint256 grossWant) {
        if (callFeeRecipient == address(0)) revert ZeroAddress();
        grossWant = _harvest(callFeeRecipient);
    }

    function balanceOf() public view override returns (uint256) {
        return _unreservedIdle() + REVENUE_STAKING.activeBalance(address(this));
    }

    function estimatedTokenAprBps() external pure override returns (uint256) {
        return 0;
    }

    /// @notice Conservatively value rewards before they are actually harvested.
    /// @dev Does not require a not-yet-configured USDC->SDT or SDT->cyvlSDT route.
    ///      Unavailable USDC pricing contributes zero rather than blocking vault deposits.
    function estimatedUnharvestedWant() external view override returns (uint256 estimatedWant) {
        uint256 poLBps = LOCKER.poLDepositShareBps();
        uint256 count = REVENUE_STAKING.rewardTokenCount();
        bool sdtObserved;
        for (uint256 i; i < count; ++i) {
            address token = REVENUE_STAKING.rewardTokens(i);
            if (token == address(0)) continue;
            uint256 held = token == address(WANT) ? 0 : IERC20(token).balanceOf(address(this));
            uint256 amount = REVENUE_STAKING.earned(address(this), token) + held;
            if (amount == 0) continue;
            if (token == address(WANT) || token == address(SDT)) {
                estimatedWant += token == address(SDT)
                    ? amount - Math.mulDiv(amount, poLBps, BPS) : amount;
                // SDT conversion mints at least the post-PoL net amount; a pool may improve output.
                if (token == address(SDT)) sdtObserved = true;
            } else if (token == USDC) {
                try OMNI_ROUTER.guardedMinOut(USDC, address(SDT), amount) returns (uint256 quotedSdt) {
                    estimatedWant += quotedSdt - Math.mulDiv(quotedSdt, poLBps, BPS);
                } catch {}
            }
        }
        if (!sdtObserved) {
            uint256 heldSdt = SDT.balanceOf(address(this));
            estimatedWant += heldSdt - Math.mulDiv(heldSdt, poLBps, BPS);
        }
    }

    function panic() external onlyOwner nonReentrant {
        _pause();
        uint256 active = REVENUE_STAKING.activeBalance(address(this));
        if (active != 0) REVENUE_STAKING.withdrawImmediate(active, address(this));
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
        _depositIdle();
    }

    function _harvest(address callFeeRecipient) internal returns (uint256 grossWant) {
        uint256 beforeWant = WANT.balanceOf(address(this));
        REVENUE_STAKING.claimRewardsSelf();

        uint256 count = REVENUE_STAKING.rewardTokenCount();
        for (uint256 i; i < count; ++i) {
            address token = REVENUE_STAKING.rewardTokens(i);
            if (token == address(0) || token == address(WANT)) continue;
            _convertHeld(token);
        }
        if (SDT.balanceOf(address(this)) != 0) _convertHeld(address(SDT));

        uint256 afterWant = WANT.balanceOf(address(this));
        grossWant = afterWant - beforeWant;
        uint256 callerFee;
        uint256 performanceFee;
        if (grossWant != 0) {
            if (callFeeRecipient != address(0) && callFeeBps != 0) {
                callerFee = Math.mulDiv(grossWant, callFeeBps, BPS);
                if (callerFee != 0) WANT.safeTransfer(callFeeRecipient, callerFee);
            }
            if (performanceFeeBps != 0) {
                performanceFee = Math.mulDiv(grossWant, performanceFeeBps, BPS);
                if (performanceFee != 0) WANT.safeTransfer(ICurveYieldVault(vault).feeReceiver(), performanceFee);
            }
        }
        _depositIdle();
        emit Harvest(callFeeRecipient, grossWant, callerFee, performanceFee);
    }

    function _convertHeld(address token) internal {
        if (token == address(SDT)) {
            _depositHeldSDT();
            return;
        }
        if (token != USDC) return; // Unknown tokens are left untouched, not misrouted.
        uint256 amount = IERC20(USDC).balanceOf(address(this));
        if (amount == 0) return;
        uint256 guarded;
        try OMNI_ROUTER.guardedMinOut(USDC, address(SDT), amount) returns (uint256 minimum) {
            guarded = minimum;
        } catch { return; } // Route not configured yet: remain liquid, no harvest blocker.
        if (guarded == 0) return;
        IERC20(USDC).forceApprove(address(OMNI_ROUTER), amount);
        try OMNI_ROUTER.swapExactInput(
            USDC, address(SDT), amount, guarded, address(this), block.timestamp
        ) returns (uint256) {} catch {
            IERC20(USDC).forceApprove(address(OMNI_ROUTER), 0);
            return;
        }
        IERC20(USDC).forceApprove(address(OMNI_ROUTER), 0);
        _depositHeldSDT();
    }

    function _depositHeldSDT() internal {
        uint256 amount = SDT.balanceOf(address(this));
        if (amount == 0) return;
        SDT.forceApprove(address(LOCKER), amount);
        LOCKER.deposit(amount, address(this));
        SDT.forceApprove(address(LOCKER), 0);
    }

    function _depositIdle() internal {
        uint256 amount = _unreservedIdle();
        if (amount == 0) return;
        WANT.forceApprove(address(REVENUE_STAKING), amount);
        REVENUE_STAKING.stake(amount);
        WANT.forceApprove(address(REVENUE_STAKING), 0);
        emit Deposit(amount);
    }

    function _unreservedIdle() internal view returns (uint256 idle) {
        uint256 balance = WANT.balanceOf(address(this));
        uint256 reserved = reservedWithdrawalAssets;
        idle = balance > reserved ? balance - reserved : 0;
    }


}
