interface ICurveYieldVlSDTToken {
    function mint(address receiver, uint256 amount) external;
    function burnForEmergencyWithdrawal(uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
    function totalSupply() external view returns (uint256);
}

interface ICurveYieldvlSDTStaking {
    function admin() external view returns (address);
    function notifyReward(address token, uint256 amount) external;
    function stake(uint256 amount) external;
    function immediateWithdrawFeePpm() external view returns (uint256);
    function previewImmediateWithdrawal(uint256 amount) external view returns (uint256 received);
    function withdrawImmediate(uint256 amount, address receiver) external returns (uint256 received);
    function requestWithdrawal(uint256 amount) external returns (uint256 id);
    function completeQueuedWithdrawal(uint256 id, address receiver) external returns (uint256 amount);
    function withdrawQueuedImmediate(uint256 id, address receiver) external returns (uint256 received);
    function WITHDRAWAL_DELAY() external view returns (uint256);
    function queuedBalance(address user) external view returns (uint256);
    function withdrawalRequests(uint256 id)
        external
        view
        returns (address owner, uint128 amount, uint64 unlockTime, bool completed);
    function claimRewardsSelf() external;
    function activeBalance(address user) external view returns (uint256);
    function rewardTokenCount() external view returns (uint256);
    function rewardTokens(uint256 index) external view returns (address);
    function earned(address user, address token) external view returns (uint256);
    function isRewardToken(address token) external view returns (bool);
}

interface ICurveYieldvlSDTLocker {
    function deposit(uint256 amount, address receiver) external returns (uint256 minted);
    function poLDepositShareBps() external view returns (uint16);
    function cyvlSdtPoLContract() external view returns (address);
    function baseSDTEquivalent(uint256 shares) external view returns (uint256);
    function forwardMerchantRevenue(uint256 amount) external;
    function claimAndForwardRevenue() external returns (uint256 usdcSent, uint256 sdtSent);
    function delegateBoost(uint256 amount, uint256 endtime, address recipient) external returns (uint256 commitmentId);
    function releaseMerchantBoostCommitment(uint256 id) external;
    function merchantDelegableBoost() external view returns (uint256);
    function daoBoostAllocation() external view returns (uint256);
    function daoDelegableBoost() external view returns (uint256);
    function adminBoostAllocation() external view returns (uint256);
    function adminDelegableBoost() external view returns (uint256);
    function marketplaceCreateListing(uint256 amount, uint256 pricePerWeek, uint256 minDuration,
        uint256 maxDuration, address paymentToken, uint256 expiry) external returns (uint256 listingId);
    function marketplaceUpdateListing(uint256 listingId, uint256 newAmount, uint256 newPricePerWeek) external;
    function marketplaceCancelListing(uint256 listingId) external;
    function marketplaceAcceptOffer(uint256 offerId, uint256 fillAmount, uint256 minTotalPayment,
        uint256 maxEffectiveDuration, bool daoSale) external returns (uint256 revenueAmount);
}
